sys_script_include.script:
function GetAllHoursRulesForStore(vStore)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var Clone = x_snc_devtools.Clone;

	var grStore = GetStoreRecord(vStore);
	if (IsValidRecord(grStore) == false)	
	{
		return false;
	}

	var aRules = [];

	var aHoursRuleSets = GetAllHoursRuleSetsForStore(grStore);
	if (aHoursRuleSets === false)
	{
		return false;
	}

	for (var nSet = 0; nSet < aHoursRuleSets.length; nSet++)
	{
		var hoursruleset = aHoursRuleSets[nSet];
		var grHoursRule = new GlideRecord('x_snc_stores_hours_rule');
		grHoursRule.addQuery('hours_rule_set','=',hoursruleset.sys_id);
		grHoursRule.query();
		while (grHoursRule.next())
		{
			var rule = Clone(grHoursRule);
			rule.activation_start_date = hoursruleset.activation_start_date;
			rule.activation_end_date = hoursruleset.activation_end_date;
			aRules.push(rule);
		}
	}

	return aRules;
}
